import React from 'react';
import { Calendar, Clock, User, Scissors } from 'lucide-react';
import { AppointmentCard } from '@/components/client/AppointmentCard';

// Mock past appointments data
const pastAppointments = [
    { id: 1, service: 'Degradê', barber: 'Lucas', date: '2026-08-10', time: '14:00', price: 'R$ 40', status: 'past' },
    { id: 2, service: 'Barba', barber: 'Marcelo', date: '2026-07-22', time: '11:30', price: 'R$ 25', status: 'past' },
];

export default function HistoryPage() {
    return (
        <div className="p-6 space-y-6">
            <h1 className="text-2xl font-light text-white">Histórico de Serviços</h1>
            <div className="grid gap-4">
                {pastAppointments.map((appt) => (
                    <AppointmentCard
                        key={appt.id}
                        service={appt.service}
                        barber={appt.barber}
                        date={appt.date}
                        time={appt.time}
                        price={appt.price}
                        status={appt.status as any}
                    />
                ))}
            </div>
        </div>
    );
}
